			onLoadedCallback?.Invoke(sprite);
		}
		public bool CheckAllowUse(bool isBattle) {
            if (!isBattle && GetParam(PrmID.F_FUNC) == 0)
                return false;

            if (Category != CategoryType.Nuts)
                return true;

            for (int i = 0; i < CheckAllowUsePrmIDs.Length; i++)
            {
                if (GetParam(CheckAllowUsePrmIDs[i]) != 0)
                    return true;
            }

            return false;
        }
